    IF Enable THEN
        (* 1. Safety check for Sample Time Ts *)
        IF TS < 0.001 THEN
            Ts_safe := 0.001;
        ELSE
            Ts_safe := Ts;
        END_IF;

        (* 2. Current Error Calculation *)
        error := SP - PV;
        Error_Out := error;

        (* 3. Proportional Term *)
        P_TERM := Kp * error;

        (* 4. Derivative Term *)
        IF Ts_safe > 0.001 THEN
            D_term := Kd * (error - error_prev) / Ts_safe;
        ELSE
            D_term := 0.0;
        END_IF;

        (* 5. Integral Term with Anti-Windup *)
        I_term := I_term + (Ki * error * Ts_safe);

        IF I_term > Out_Max THEN
            I_term := Out_Max;
        ELSIF I_term < Out_Min THEN
            I_term := Out_Min;
        END_IF;

        (* 6. Output Calculation & Clamping *)
        Pidout_temp := P_TERM + I_term + D_term;

        IF Pidout_temp > Out_Max THEN
            Pidout := Out_Max;
        ELSIF Pidout_temp < Out_Min THEN
            Pidout := Out_Min;
        ELSE
            Pidout := Pidout_temp;
        END_IF;

        (* 7. Save Error for Next Cycle *)
        error_prev := error;

    ELSE
        (* Reset logic when Disabled *)
        I_term := 0.0;
        error_prev := 0.0;
        Pidout := 0.0;
        Error_Out := 0.0;
    END_IF;


IF (NOT Enable) THEN
    RT := 0.0;

    RT_Counting := TRUE; (* Reset and prepare to count on next start *)

ELSIF Enable AND RT_Counting THEN
    (* 2. While process variable is below Setpoint, accumulate scan time *)
    IF PV < SP THEN
        RT := RT + TS; (* TS is your scan time, e.g., 0.001s *)
    ELSE
        (* 3. PV has reached or exceeded SP: Stop counting *)
        RT_Counting := FALSE;
    END_IF;
END_IF;

    IF RESET THEN 
    DONE := FALSE;
        Control_Out := 0.0;
        CYCLE_COUNT := 0;
        CYCLE_TIMER := 0.0;
        T_MAX := PV;
        t_min := PV;
        BUSY := TRUE;
        START := FALSE;
        PU := 0.0001;
        AMP := 0.0;
    END_IF;

    IF NOT START THEN
        DONE := FALSE;
        Control_Out := 0.0;
        CYCLE_COUNT := 0;
        CYCLE_TIMER := 0.0;
        T_MAX := PV;
        t_min := PV;
    ELSIF NOT DONE THEN
        CYCLE_TIMER := CYCLE_TIMER + TS;

        (* Peak & Trough Tracking *)
        IF PV > T_MAX THEN T_MAX := PV; END_IF;
        IF PV < t_min THEN t_min := PV; END_IF;

        (* Relay Switch *)
        IF RELAY_STATE AND (PV >= (SP + HYSTERES)) THEN
            RELAY_STATE := FALSE;
        ELSIF (NOT RELAY_STATE) AND (PV <= (SP - HYSTERES)) THEN
            RELAY_STATE := TRUE;
        END_IF;

        IF RELAY_STATE THEN Control_Out := Relay_High; 
          ELSE Control_Out := RELAY_LOW; END_IF;

        (* Detect Upward Zero-Crossing *)
        IF (prev_PV < SP) AND (PV >= SP) THEN
            CYCLE_COUNT := CYCLE_COUNT + 1;

            IF CYCLE_COUNT = 100 THEN
                CYCLE_TIMER := 0.0; (* Start timer for full period *)
                T_MAX := PV;
                t_min := PV;

            ELSIF CYCLE_COUNT = 200 THEN

                DONE := TRUE;
                BUSY := FALSE;
                Control_Out := 0.0;
            END_IF;
        END_IF;
    END_IF;
    PU := CYCLE_TIMER /100.0;
    AMP := (T_MAX - t_min) / 2.0;
    prev_PV := PV;


    (* 1. Start timer on START or RESET trigger *)
IF RESET OR (NOT START) THEN
    RT := 0.0;
    RT_Counting := TRUE; (* Reset and prepare to count on next start *)
ELSIF START AND RT_Counting THEN
    (* 2. While process variable is below Setpoint, accumulate scan time *)
    IF PV < SP THEN
        RT := RT + TS; (* TS is your scan time, e.g., 0.001s *)
    ELSE
        (* 3. PV has reached or exceeded SP: Stop counting *)
        RT_Counting := FALSE;
    END_IF;
END_IF;

IF AMP <= 0.001 THEN AMP := 0.001 ; END_IF;
IF PU <= 0.001 THEN PU := 0.001 ; END_IF;

KU := 400.0 /(3.1415926535 * AMP);
KP := 0.2 * KU;
KI := 0.4 * KU / PU;
KD := 0.03 * KU * PU;

