(* this fb use the RTC_EXTRACT_ud fb to calculate time and date of work , you can just enter entry and leave hour and it will give you currient hour , date and worktime status ,the weekends and official free days are precounted, you can add an exceptional free day date with day_f and month_f inputs. bilal chemloul great you, *)
(* Call RTC_EXTRACT_ud and assign UINT variables *)
Curr_Time( uiMonth =>MONTH (*UINT*), uiDay =>Day (*UINT*), uiDayOfWeek =>DayOfWeek (*UINT*), uiHour =>HOUR (*UINT*), uiMinute => minute(*UINT*), uiSecond => second (*UINT*), udiMinOfDay => minofday(*UDINT*));
(* Evaluate time_of_work condition: Evaluates to TRUE under any of the following: 1. Outside working hours (HOUR < HOUR_EN or HOUR >= HOUR_OUT) 2. Weekend days (Friday = 5, Saturday = 6) 3. National and customary holidays *)
IF (minofday < (HOUR_EN *60 + MIN_EN)) or (minofday >= (HOUR_out *60 + MIN_out)) OR (DayOfWeek = 5) OR (DayOfWeek = 6) OR (Day = 5 AND MONTH = 7) (* Independence Day *) OR (Day = 1 AND MONTH = 5) (* Labor Day *) OR (Day = 1 AND MONTH = 1) (* New Year *) OR (Day = 12 AND MONTH = 1) (* Yennayer *) OR (Day = 1 AND MONTH = 11) (* Revolution Day *) OR (Day = DAY_F AND MONTH = MONTH_F) (* Dynamic holiday parameter *) THEN time_of_work := false; ELSE time_of_work := true; END_IF;

(* this fb use the plc rtc to extract time and date parameters, 
  you can modify its output variable to what you need only.
  bilal chemloul great you, *)

  (* Get current PLC time *)
  RTC_Clock(
      IN := FALSE,
      CDT => dtCurrent
  );

  (* Convert current DT to seconds since 1970 *)
  udiEpoch := DT_TO_UDINT(dtCurrent);

  (* Split into days and time *)
  udiDays := udiEpoch / 86400;
  udiSecOfDay := udiEpoch MOD 86400;
  udiMinOfDay := udiSecOfDay / 60;
  (* Time (delete "1 +" if the hours advanced by 1 ) *)
  uiHour := 1 + udiSecOfDay / 3600;

  uiMinute := (udiSecOfDay MOD 3600) / 60 ;

  uiSecond := udiSecOfDay MOD 60 ;

  (* Day of week: 1=Monday ... 7=Sunday *)
  uiDayOfWeek :=((udiDays + 3) MOD 7) + 1;

  (* Gregorian calendar *)
  udiZ := udiDays + 719468;
  udiEra := udiZ / 146097;

  udiDoe :=
      udiZ - (udiEra * 146097);

  udiYoe :=
      (
          udiDoe
          - (udiDoe / 1460)
          + (udiDoe / 36524)
          - (udiDoe / 146096)
      ) / 365;

  udiY :=
      udiYoe + (udiEra * 400);

  udiDoy :=
      udiDoe
      - (
          365 * udiYoe
          + (udiYoe / 4)
          - (udiYoe / 100)
      );

  udiMp :=
      (5 * udiDoy + 2) / 153;

  udiD :=
      udiDoy
      - ((153 * udiMp + 2) / 5)
      + 1;

  IF udiMp < 10 THEN
      udiM := udiMp + 3;
  ELSE
      udiM := udiMp - 9;
  END_IF;

  IF udiM <= 2 THEN
      udiY := udiY + 1;
  END_IF;

  (* Date outputs *)
  uiYear := udiY;
  uiMonth :=udiM;
  uiDay := udiD;

  (* Leap year *)
  xIsLeapYear :=
      ((uiYear MOD 4 = 0) AND (uiYear MOD 100 <> 0))
      OR
      (uiYear MOD 400 = 0);

  (* Days in year *)
  IF xIsLeapYear THEN
      uiDaysInYear := 366;
  ELSE
      uiDaysInYear := 365;
  END_IF;

  (* Days in month *)
  CASE uiMonth OF
      1, 3, 5, 7, 8, 10, 12:
          uiDaysInMonth := 31;

      4, 6, 9, 11:
          uiDaysInMonth := 30;

      2:
          IF xIsLeapYear THEN
              uiDaysInMonth := 29;
          ELSE
              uiDaysInMonth := 28;
          END_IF;

      ELSE
          uiDaysInMonth := 0;
  END_CASE;

  (* Day of year *)
  CASE uiMonth OF
      1:  uiDayOfYear := uiDay;
      2:  uiDayOfYear := 31 + uiDay;
      3:  uiDayOfYear := 59 + uiDay;
      4:  uiDayOfYear := 90 + uiDay;
      5:  uiDayOfYear := 120 + uiDay;
      6:  uiDayOfYear := 151 + uiDay;
      7:  uiDayOfYear := 181 + uiDay;
      8:  uiDayOfYear := 212 + uiDay;
      9:  uiDayOfYear := 243 + uiDay;
      10: uiDayOfYear := 273 + uiDay;
      11: uiDayOfYear := 304 + uiDay;
      12: uiDayOfYear := 334 + uiDay;
      ELSE
          uiDayOfYear := 0;
  END_CASE;

  IF xIsLeapYear AND (uiMonth > 2) THEN
      uiDayOfYear := uiDayOfYear + 1;
  END_IF;

  xValid := TRUE;
